private fun androidx.compose.foundation.layout.ColumnScope.SessionPane(
    client: TansrAgentClient,
    session: AgentSession,

val connection by session.collectConnectionStateAsStateWithLifecycle()
val historyRequests = remember(client, session) { DemoHistoryImageRequestState() }
var historyRevision by remember(client, session) { mutableStateOf(0) }
var historyAttempt by remember(client, session) { mutableStateOf(0) }
val historyDelivery = session.delivery
DisposableEffect(historyRequests) { onDispose { historyRequests.close() } }
LaunchedEffect(client, session, historyAttempt, historyDelivery) {
    val ticket = historyRequests.begin(client, session, session.sessionId)
    try {
        val history = client.history(session.sessionId)
        check(history.sessionId == session.sessionId) { "Foreign session history" }
        val projection = withContext(Dispatchers.Default) {
            val context = kotlin.coroutines.coroutineContext
            DemoHistoryImages.build(history, historyDelivery, imageBounds = { bytes ->
                val bounds = android.graphics.BitmapFactory.Options().apply { inJustDecodeBounds = true }
                android.graphics.BitmapFactory.decodeByteArray(bytes, 0, bytes.size, bounds)
                bounds.outWidth to bounds.outHeight
            }, checkActive = { context.ensureActive() })
        }
        kotlin.coroutines.coroutineContext.ensureActive()
        if (historyRequests.complete(ticket, projection)) {
            historyRevision++
            // Await only the local SDK watermark, never poll history or model endpoints.
            var remaining = 50
            while (session.lastConsumedSeq < history.lastSeq && remaining-- > 0) delay(100)
            kotlin.coroutines.coroutineContext.ensureActive()
            if (historyRequests.accepts(ticket)) historyRevision++
        }
    } catch (cancelled: kotlinx.coroutines.CancellationException) {
        historyRequests.cancel(ticket)
        throw cancelled
    } catch (_: Exception) {
        if (historyRequests.fail(ticket)) historyRevision++
    }
}
val historyPresentation = remember(historyRevision, view, connection, historyDelivery) {
    historyRequests.projection?.present(view, session.lastConsumedSeq, historyDelivery)
        ?: DemoHistoryImages.Presentation(view, null)
}

TansrErrorBanner(view.lastError)
val historyWarning = historyRequests.error ?: historyPresentation.warning
if (historyWarning != null) {
    Text(historyWarning, style = MaterialTheme.typography.labelMedium)
    OutlinedButton(onClick = { historyAttempt++ }) { Text("重试历史图片") }
}

