package com.tansr.sdk.sample

import com.tansr.sdk.client.SessionHistory
import com.tansr.sdk.protocol.IRBlock
import com.tansr.sdk.view.SessionViewDelivery
import com.tansr.sdk.view.SessionViewState
import com.tansr.sdk.view.UIImagePart
import com.tansr.sdk.view.UIMessage
import com.tansr.sdk.view.UIMessagePart
import com.tansr.sdk.view.UITextPart
import com.tansr.sdk.view.viewStateFromHistory
import java.security.MessageDigest
import java.util.Base64

/** Demo presentation compatibility for public SDK 0.4.0, which omits history Image blocks. */
internal class DemoHistoryImages private constructor(
    val sessionId: String,
    val lastSeq: Long,
    private val baseline: List<UIMessage>,
    private val enhanced: List<UIMessage>,
    private val delivery: SessionViewDelivery,
    private val warning: String?,
    val validatedImageHashes: List<String>,
) {
    data class Presentation(val view: SessionViewState, val warning: String?)

    fun present(live: SessionViewState, consumedSeq: Long, currentDelivery: SessionViewDelivery): Presentation {
        if (currentDelivery != delivery) return Presentation(live, "历史图片显示方式已变化，请重试加载")
        if (consumedSeq < lastSeq) return Presentation(live, "正在等待会话历史同步，图片稍后恢复")
        // Idempotence also covers callers that already hold the exact enhanced prefix.
        if (live.messages.take(enhanced.size) == enhanced) return Presentation(live, warning)
        if (live.messages.size < baseline.size) return Presentation(live, "历史图片尚未对齐，请重试加载")
        val byId = enhanced.associateBy { it.id }
        for (index in baseline.indices) {
            val actual = live.messages[index]
            val original = baseline[index]
            // Never strip arbitrary live images: only either complete known message is accepted.
            if (actual != original && actual != byId[original.id]) {
                return Presentation(live, "历史图片尚未对齐，请重试加载")
            }
        }
        val tail = live.messages.drop(baseline.size)
        if (enhanced.size > baseline.size && tail.any { it.role == "user" && it.parts.any { part -> part is UIImagePart } }) {
            return Presentation(live, "纯图片历史与实时图片尚未对齐，请重试加载")
        }
        if (tail.any { row -> enhanced.any { it.id == row.id } }) {
            return Presentation(live, "历史图片标识冲突，已保留当前消息")
        }
        return Presentation(live.copy(messages = enhanced + tail), warning)
    }

    companion object {
        // Preview budgets, not SDK/wire upload limits. Over-budget images stay visible as explanations.
        const val MAX_IMAGE_BYTES = 8 * 1024 * 1024
        const val MAX_TOTAL_BYTES = 16 * 1024 * 1024
        const val MAX_IMAGE_COUNT = 64
        const val MAX_HISTORY_MESSAGES = 2000
        const val MAX_PROJECTION_WORK = 100_000L
        const val MAX_DIMENSION = 1280 // Same long-edge limit as original ImageAttachment.
        private val mimePattern = Regex("^image/(png|jpeg|webp|gif)$")

        fun build(
            history: SessionHistory,
            delivery: SessionViewDelivery,
            imageBounds: (ByteArray) -> Triple<Int, Int, String?>,
            checkActive: () -> Unit = {},
        ): DemoHistoryImages {
            checkActive()
            require(history.messages.size <= MAX_HISTORY_MESSAGES) { "历史消息超过 2000 条预览预算" }
            val imageRows = history.messages.withIndex().filter { row ->
                row.value.role == "user" && row.value.blocks.any { it is IRBlock.Image }
            }
            require(history.messages.size.toLong() * (1L + 2L * imageRows.size) <= MAX_PROJECTION_WORK) {
                "历史图片投影超过本机预览预算"
            }
            val baseline = viewStateFromHistory(history.messages, delivery).view.messages
            val enhanced = baseline.toMutableList()
            val namespace = MessageDigest.getInstance("SHA-256").digest(history.sessionId.toByteArray())
                .take(12).joinToString("") { "%02x".format(it) }
            var inserts = 0
            var totalBytes = 0L
            var imageCount = 0
            var warnings = 0
            val imageHashes = mutableListOf<String>()
            fun imagePart(image: IRBlock.Image): UIMessagePart {
                checkActive()
                imageCount++
                val reason = when {
                    imageCount > MAX_IMAGE_COUNT -> "超过每次 64 张预览预算"
                    !mimePattern.matches(image.mime) -> "不支持的图片格式"
                    image.data.length > ((MAX_IMAGE_BYTES.toLong() + 2) / 3 * 4) -> "超过单图 8 MiB 预览预算"
                    else -> null
                }
                fun unavailable(message: String): UIMessagePart {
                    warnings++
                    return UITextPart("[历史图片无法预览：$message；原消息仍保留]")
                }
                if (reason != null) return unavailable(reason)
                val bytes = try { Base64.getDecoder().decode(image.data) } catch (_: IllegalArgumentException) {
                    return unavailable("图片编码无效")
                }
                checkActive()
                if (bytes.isEmpty() || bytes.size > MAX_IMAGE_BYTES) return unavailable("图片字节超出预览预算")
                if (totalBytes + bytes.size > MAX_TOTAL_BYTES) return unavailable("超过合计 16 MiB 预览预算")
                totalBytes += bytes.size
                val bounds = imageBounds(bytes)
                checkActive()
                if (bounds.third != image.mime) return unavailable("图片格式与内容不一致")
                if (bounds.first <= 0 || bounds.second <= 0 || maxOf(bounds.first, bounds.second) > MAX_DIMENSION) {
                    return unavailable("图片不可解码或尺寸超过 1280 像素")
                }
                imageHashes.add(MessageDigest.getInstance("SHA-256").digest(bytes).joinToString("") { "%02x".format(it) })
                return UIImagePart(image.mime, image.data)
            }
            for ((irIndex, message) in imageRows) {
                checkActive()
                require(message.blocks.all { it is IRBlock.Text || it is IRBlock.Image }) {
                    "历史图片含不支持的混合内容，已保留当前消息"
                }
                // Complete prefixes preserve the public projector's cross-message tool pairing.
                val before = viewStateFromHistory(history.messages.take(irIndex), delivery).view.messages
                checkActive()
                val through = viewStateFromHistory(history.messages.take(irIndex + 1), delivery).view.messages
                checkActive()
                val parts = message.blocks.mapNotNull { block ->
                    when (block) {
                        is IRBlock.Text -> block.text.takeIf { it.isNotEmpty() }?.let(::UITextPart)
                        is IRBlock.Image -> imagePart(block)
                        else -> null
                    }
                }
                val slot = before.size
                if (through.size == before.size) {
                    require(message.blocks.filterIsInstance<IRBlock.Text>().all { it.text.isEmpty() }) {
                        "历史图片槽位不匹配，已保留当前消息"
                    }
                    val id = "demo-history-image:$namespace:$irIndex"
                    require(enhanced.none { it.id == id }) { "历史图片标识冲突" }
                    enhanced.add(slot + inserts, UIMessage(id, "user", parts))
                    inserts++
                } else {
                    require(through.size == before.size + 1 && slot < baseline.size) { "历史图片槽位不匹配" }
                    val original = baseline[slot]
                    require(original.id == through.last().id && original.role == "user") { "历史图片消息归属不匹配" }
                    val originalTexts = message.blocks.filterIsInstance<IRBlock.Text>()
                        .mapNotNull { it.text.takeIf(String::isNotEmpty)?.let(::UITextPart) }
                    require(original.parts == originalTexts) {
                        "历史图片文本投影不匹配，已保留当前消息"
                    }
                    enhanced[slot + inserts] = original.copy(parts = parts)
                }
            }
            checkActive()
            return DemoHistoryImages(history.sessionId, history.lastSeq, baseline, enhanced, delivery,
                if (warnings > 0) "$warnings 张历史图片无法预览，原因已在原位置显示" else null, imageHashes.toList())
        }
    }
}

/** Main-thread request generation: old account/connection/session responses cannot commit. */
internal class DemoHistoryImageRequestState {
    data class Ticket(val generation: Long, val client: Any, val session: Any, val sessionId: String)
    private var generation = 0L
    private var current: Ticket? = null
    var projection: DemoHistoryImages? = null
        private set
    var error: String? = null
        private set

    fun begin(client: Any, session: Any, sessionId: String): Ticket {
        if (current?.let { it.client === client && it.session === session && it.sessionId == sessionId } != true) projection = null
        error = null
        return Ticket(++generation, client, session, sessionId).also { current = it }
    }
    fun accepts(ticket: Ticket): Boolean = current?.let {
        it.generation == ticket.generation && it.client === ticket.client && it.session === ticket.session && it.sessionId == ticket.sessionId
    } == true
    fun complete(ticket: Ticket, value: DemoHistoryImages): Boolean {
        if (!accepts(ticket) || value.sessionId != ticket.sessionId) return false
        projection = value
        error = null
        return true
    }
    fun fail(ticket: Ticket): Boolean {
        if (!accepts(ticket)) return false
        error = "历史图片未加载，原消息仍保留；可重试"
        return true
    }
    fun cancel(ticket: Ticket) { if (accepts(ticket)) { generation++; current = null } }
    fun close() { generation++; current = null; projection = null; error = null }
}
